#include <bits/stdc++.h>
using namespace std;

int dig(int n)
{
    int sum = 0;
    while (n)
    {
        sum++;
        n /= 10;
    }
    return sum;
}

int main()
{
    int T;
    cin >> T;

    int ar[6];
    int p;
    for (int i = 0; i < 6; i++)
    {
        cin >> p;
        ar[i] = p;
    }

    int q;
    cin >> q;

    int n;
    cin >> n;

    vector<int> dp(T, 0);
    int sum = 9;

    if (T > 9)
        dp[0] = 9;

    for (int i = 1; i < T; i++)
    {
        if (sum + ((10 * i) + 9) <= T)
        {
            dp[i] = (10 * i) + 9;
            sum += dp[i];
        }
        else if (sum + ((10 * i) + 6) <= T)
        {
            dp[i] = (10 * i) + 6;
            sum += dp[i];
        }
        else if (sum + ((10 * i) + 3) <= T)
        {
            dp[i] = (10 * i) + 3;
            sum += dp[i];
        }
        else if (sum > T)
        {
            int dif = sum - T;
            for (int j = 1; j >= 0; j--)
            {
                if (dif <= dp[j])
                {
                    dp[j] -= dif;
                    sum -= dif;
                    break;
                }
            }
        }
    }

    int fortune = 0;
    for (int i = 0; i < T; i++)
    {
        if ((dp[i] % 10) % 3 == 0)
        {
            fortune += ((dp[i] % 10) / 3) * (dig(dp[i]) - 1);
        }
    }

    cout << fortune << endl;
    return 0;
}

